// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract BlockchainLog {
    struct Log {
        string tableName;
        uint256 recordId;
        string action;
        string hash;
        address senderAddress;
        uint256 timestamp;
    }

    mapping(uint256 => Log) private logs;
    uint256 public logCounter;

    event LogAdded(
        uint256 logId,
        string tableName,
        uint256 recordId,
        string action,
        string hash,
        address senderAddress,
        uint256 timestamp
    );

    /// @notice Thêm một bản ghi log vào blockchain
    function addLog(
        string memory _tableName,
        uint256 _recordId,
        string memory _action,
        string memory _hash
    ) public {
        logs[logCounter] = Log(
            _tableName,
            _recordId,
            _action,
            _hash,
            msg.sender,
            block.timestamp
        );

        emit LogAdded(
            logCounter,
            _tableName,
            _recordId,
            _action,
            _hash,
            msg.sender,
            block.timestamp
        );

        logCounter++;
    }

    /// @notice Lấy thông tin log theo ID
    function getLog(
        uint256 _logId
    )
        public
        view
        returns (
            string memory tableName,
            uint256 recordId,
            string memory action,
            string memory hash,
            address senderAddress,
            uint256 timestamp
        )
    {
        require(_logId < logCounter, "Log does not exist");

        Log memory log = logs[_logId];

        return (
            log.tableName,
            log.recordId,
            log.action,
            log.hash,
            log.senderAddress,
            log.timestamp
        );
    }

    /// @notice Trả về tổng số log đã lưu
    function getLogCount() public view returns (uint256) {
        return logCounter;
    }
}
